-- Schema only. Performance indexes and partitions intentionally live in database-labs.
CREATE TABLE settlement (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, settlement_no VARCHAR2(64) NOT NULL UNIQUE, seller_id NUMBER NOT NULL, period_start TIMESTAMP NOT NULL, period_end TIMESTAMP NOT NULL, gross_amount NUMBER(19,2) NOT NULL, commission_amount NUMBER(19,2) NOT NULL, payable_amount NUMBER(19,2) NOT NULL, status VARCHAR2(32) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE settlement_line (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, settlement_id NUMBER NOT NULL REFERENCES settlement(id), seller_order_id VARCHAR2(64) NOT NULL UNIQUE, gross_amount NUMBER(19,2) NOT NULL, commission_amount NUMBER(19,2) NOT NULL, payable_amount NUMBER(19,2) NOT NULL);
CREATE TABLE outbox_event (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_id VARCHAR2(36) NOT NULL UNIQUE, aggregate_id VARCHAR2(128) NOT NULL, event_type VARCHAR2(128) NOT NULL, payload_json CLOB NOT NULL, status VARCHAR2(32) NOT NULL, created_at TIMESTAMP NOT NULL, processed_at TIMESTAMP NULL);

CREATE TABLE inbox_event (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, consumer_name VARCHAR2(128) NOT NULL, event_id VARCHAR2(36) NOT NULL, processed_at TIMESTAMP NOT NULL, CONSTRAINT uq_settlement_inbox UNIQUE(consumer_name,event_id));
